export type ValidatedPermisHubSign = PermanentSign & { confidence: 'high'; needsReview: false }

export const VALIDATED_PERMISHUB_SIGNS: ValidatedPermisHubSign[] = PERMISHUB_SIGNS.filter((sign): sign is ValidatedPermisHubSign => sign.confidence === 'high' && !sign.needsReview)

export const REVIEW_PERMISHUB_SIGNS = PERMISHUB_SIGNS.filter((sign) => sign.needsReview)

export const getPermisHubSign = (id: string) => VALIDATED_PERMISHUB_SIGNS.find((sign) => sign.id === id)

export const getValidatedPermisHubSignByCode = (officialCode: string) => VALIDATED_PERMISHUB_SIGNS.find((sign) => sign.officialCode === officialCode)

export const getPermisHubReviewCandidate = (id: string) => REVIEW_PERMISHUB_SIGNS.find((sign) => sign.id === id)
